import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { saveProfile } from '../../api/onboarding';
import { Building2, User as UserIcon, Loader2 } from 'lucide-react';

export const ProfileSetupPage: React.FC = () => {
  const { user, logout, refreshUser } = useAuth();
  const navigate = useNavigate();

  // Extract initial names if available from real displayName (not auto-generated email prefix)
  const rawDisplayName = user?.displayName || '';
  const isAutoGenerated = /\d|_/.test(rawDisplayName) || rawDisplayName.includes('@');
  const nameParts = (!isAutoGenerated ? rawDisplayName : '').trim().split(' ');
  const defaultFirst = nameParts[0] || '';
  const defaultLast = nameParts.slice(1).join(' ') || '';

  const [firstName, setFirstName] = useState(defaultFirst);
  const [lastName, setLastName] = useState(defaultLast);
  const [accountType, setAccountType] = useState<'business' | 'individual'>('business');
  const [orgName, setOrgName] = useState('');
  const [workspaceName, setWorkspaceName] = useState('Default workspace');

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!firstName.trim()) {
      setError('First name is required');
      return;
    }
    if (accountType === 'business' && !orgName.trim()) {
      setError('Organisation name is required for Business accounts');
      return;
    }
    if (!workspaceName.trim()) {
      setError('Workspace name is required');
      return;
    }

    setError('');
    setIsLoading(true);

    try {
      await saveProfile({
        firstName: firstName.trim(),
        lastName: lastName.trim() || undefined,
        accountType,
        orgName: accountType === 'business' ? orgName.trim() : undefined,
        workspaceName: workspaceName.trim(),
      });
      await refreshUser();
      navigate('/onboarding/industries');
    } catch (err: any) {
      setError(err.message || 'Failed to set up profile. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDifferentAccount = async () => {
    await logout();
    navigate('/login');
  };

  return (
    <div className="min-h-screen bg-[#050814] flex flex-col justify-center items-center px-4 py-12 relative overflow-hidden select-none">
      {/* Background ambient lighting effects matching login theme */}
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[700px] h-[350px] bg-blue-600/12 rounded-full blur-[140px] pointer-events-none" />
      <div className="absolute -bottom-36 -left-36 w-[560px] h-[560px] rounded-full border border-blue-500/20 bg-gradient-to-tr from-blue-600/20 via-sky-500/5 to-transparent blur-xl pointer-events-none" />
      
      {/* Luminous orbital arc in bottom-left corner */}
      <svg className="absolute -bottom-16 -left-16 w-[450px] h-[450px] pointer-events-none opacity-30" viewBox="0 0 400 400" fill="none">
        <path d="M 0 400 A 360 360 0 0 1 360 40" stroke="url(#setupArcBlueGrad)" strokeWidth="2.5" />
        <defs>
          <linearGradient id="setupArcBlueGrad" x1="0%" y1="100%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#38bdf8" stopOpacity="0.8" />
            <stop offset="60%" stopColor="#2563eb" stopOpacity="0.4" />
            <stop offset="100%" stopColor="#4f46e5" stopOpacity="0" />
          </linearGradient>
        </defs>
      </svg>

      {/* Bottom-right ambient aura */}
      <div className="absolute -bottom-28 -right-28 w-[450px] h-[450px] bg-blue-600/10 rounded-full blur-[120px] pointer-events-none" />

      <div className="w-full max-w-[440px] flex flex-col z-10 animate-fade-in">
        {/* Brand Header: Samvada soundwave logo */}
        <div className="flex items-center gap-2.5 mb-7">
          <div className="w-8 h-8 rounded-lg bg-indigo-600/20 border border-indigo-500/30 flex items-center justify-center gap-1 shadow-md shadow-indigo-500/10">
            <div className="w-0.5 h-2.5 bg-indigo-500 rounded-full animate-pulse" />
            <div className="w-0.5 h-4.5 bg-indigo-400 rounded-full" />
            <div className="w-0.5 h-3 bg-indigo-500 rounded-full" />
            <div className="w-0.5 h-1.5 bg-indigo-600 rounded-full" />
          </div>
          <span className="text-xl font-bold text-white tracking-tight">Samvada AI</span>
        </div>

        {/* 2-Pill Progress Bar: Left filled indigo, Right inactive dark */}
        <div className="flex items-center gap-2.5 mb-7">
          <div className="h-1.5 w-16 rounded-full bg-indigo-500 shadow-sm shadow-indigo-500/30" />
          <div className="h-1.5 w-16 rounded-full bg-[#272832]" />
        </div>

        {/* Title & Subtitle */}
        <div className="mb-7">
          <h1 className="text-3xl font-bold text-white tracking-tight mb-1.5">Tell us about you</h1>
          <p className="text-sm text-zinc-400">A few details to set up your workspace</p>
        </div>

        {error && (
          <div className="mb-5 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-xs text-red-400">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex flex-col">
          {/* First name & Last name (2 columns) */}
          <div className="grid grid-cols-2 gap-3.5 mb-5">
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1.5">
                First name<span className="text-red-500">*</span>
              </label>
              <input
                id="first-name-input"
                type="text"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
                placeholder="Yash"
                required
                className="w-full bg-[#050608] border border-zinc-800/90 rounded-lg px-3.5 py-2.5 text-sm text-white placeholder-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1.5">
                Last name
              </label>
              <input
                id="last-name-input"
                type="text"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
                placeholder="Jaiswal"
                className="w-full bg-[#050608] border border-zinc-800/90 rounded-lg px-3.5 py-2.5 text-sm text-white placeholder-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition"
              />
            </div>
          </div>

          {/* How will you use Samvada? Toggle buttons */}
          <div className="mb-5">
            <label className="block text-xs font-medium text-zinc-300 mb-2">
              How will you use Samvada AI?
            </label>
            <div className="flex items-center gap-3">
              <button
                id="business-toggle-btn"
                type="button"
                onClick={() => setAccountType('business')}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl border text-xs font-medium transition cursor-pointer ${
                  accountType === 'business'
                    ? 'border-indigo-500 bg-[#0d1026] text-indigo-400 ring-1 ring-indigo-500/50'
                    : 'border-zinc-800 bg-[#050608] text-zinc-400 hover:border-zinc-700 hover:text-zinc-200'
                }`}
              >
                <Building2 className="w-4 h-4" />
                <span>Business</span>
              </button>

              <button
                id="individual-toggle-btn"
                type="button"
                onClick={() => setAccountType('individual')}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl border text-xs font-medium transition cursor-pointer ${
                  accountType === 'individual'
                    ? 'border-indigo-500 bg-[#0d1026] text-indigo-400 ring-1 ring-indigo-500/50'
                    : 'border-zinc-800 bg-[#050608] text-zinc-400 hover:border-zinc-700 hover:text-zinc-200'
                }`}
              >
                <UserIcon className="w-4 h-4" />
                <span>Individual</span>
              </button>
            </div>
          </div>

          {/* Organisation name (shown when Business) */}
          {accountType === 'business' && (
            <div className="mb-5 animate-fade-in">
              <label className="block text-xs font-medium text-zinc-300 mb-1.5">
                Organisation name<span className="text-red-500">*</span>
              </label>
              <input
                id="org-name-input"
                type="text"
                value={orgName}
                onChange={(e) => setOrgName(e.target.value)}
                placeholder="Name of your organisation"
                required
                className="w-full bg-[#050608] border border-zinc-800/90 rounded-lg px-3.5 py-2.5 text-sm text-white placeholder-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition"
              />
            </div>
          )}

          {/* Workspace name */}
          <div className="mb-6">
            <label className="block text-xs font-medium text-zinc-300 mb-1.5">
              Workspace name<span className="text-red-500">*</span>
            </label>
            <input
              id="workspace-name-input"
              type="text"
              value={workspaceName}
              onChange={(e) => setWorkspaceName(e.target.value)}
              placeholder="Default workspace"
              required
              className="w-full bg-[#050608] border border-zinc-800/90 rounded-lg px-3.5 py-2.5 text-sm text-white placeholder-zinc-600 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition"
            />
          </div>

          {/* Solid white Continue button */}
          <button
            id="continue-btn"
            type="submit"
            disabled={isLoading}
            className="w-full bg-white text-black font-semibold py-3 px-4 rounded-xl hover:bg-zinc-200 active:scale-[0.99] transition-all text-sm sm:text-base cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 mb-6 shadow-sm"
          >
            {isLoading ? <Loader2 className="w-4 h-4 animate-spin text-black" /> : 'Continue'}
          </button>

          {/* Bottom link: Signed in with the wrong account? */}
          <div className="text-center space-y-1">
            <p className="text-xs text-zinc-500">Signed in with the wrong account?</p>
            <button
              id="different-account-btn"
              type="button"
              onClick={handleDifferentAccount}
              className="inline-flex items-center gap-1.5 text-xs text-zinc-300 hover:text-white font-medium transition cursor-pointer"
            >
              <span>→] Login with a different account</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};
